def roman_to_int(s):
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    if not s:
        return 0
    s = s.upper().strip()
    total = 0
    prev = 0
    for ch in reversed(s):
        if ch not in values:
            raise ValueError(f"Invalid Roman numeral character: {ch!r}")
        curr = values[ch]
        if curr < prev:
            total -= curr
        else:
            total += curr
        prev = curr
    return total
